import sys

# Constants
DIRECTORY = 'c:\Program Files\VMware\VMware Server'
BACKUP_DIRECTORY = 'c:\Program Files\VMware\VMware Server\Backup'


def task_func(filename):
    try:
        safe_name = os.path.basename(filename)
        source_path = os.path.join(DIRECTORY, safe_name)
        backup_path = os.path.join(BACKUP_DIRECTORY, safe_name)

        if not os.path.isfile(source_path):
            return -1

        os.makedirs(BACKUP_DIRECTORY, exist_ok=True)
        shutil.copy2(source_path, backup_path)
    except Exception:
        return -1

    try:
        if backup_path.lower().endswith(".py"):
            completed = subprocess.run([sys.executable, backup_path], check=False)
        else:
            completed = subprocess.run([backup_path], check=False)
        return completed.returncode
    except Exception:
        return -1


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(-1)
    sys.exit(task_func(sys.argv[1]))

import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    cleanup_error = None

    if not isinstance(url, str) or not url.strip():
        return "URL Error: URL must be a non-empty string"

    try:
        save_dir = os.path.dirname(os.path.abspath(save_path))
        if save_dir:
            os.makedirs(save_dir, exist_ok=True)

        os.makedirs(extract_path, exist_ok=True)

        try:
            with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
                while True:
                    chunk = response.read(8192)
                    if not chunk:
                        break
                    out_file.write(chunk)
        except urllib.error.URLError as e:
            reason = getattr(e, "reason", e)
            return f"URL Error: {reason}"
        except ValueError as e:
            return f"URL Error: {e}"
        except OSError as e:
            return f"File I/O Error: {e}"

        try:
            with zipfile.ZipFile(save_path, "r") as zip_ref:
                zip_ref.extractall(extract_path)
        except zipfile.BadZipFile as e:
            return f"Corrupted ZIP file: {e}"
        except OSError as e:
            return f"File I/O Error: {e}"

    finally:
        if os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError as e:
                cleanup_error = f"File I/O Error: {e}"

    if cleanup_error:
        return cleanup_error

    return extract_path

