from openpyxl import load_workbook


def task_func(directory_path='./xlsx_files/'):
    processed_files = 0
    pattern = os.path.join(directory_path, '*.xlsx')

    for file_path in glob.glob(pattern):
        if os.path.basename(file_path).startswith('~$'):
            continue

        try:
            workbook = load_workbook(file_path)
        except Exception:
            continue

        changed = False
        for worksheet in workbook.worksheets:
            for row in worksheet.iter_rows():
                for cell in row:
                    if type(cell).__name__ != 'Cell':
                        continue
                    if isinstance(cell.value, str) and cell.data_type != 'f':
                        new_value = cell.value.replace('"', '\\\\"')
                        if new_value != cell.value:
                            cell.value = new_value
                            changed = True

        try:
            workbook.save(file_path)
            processed_files += 1
        except Exception:
            continue

    return processed_files

import os
from pathlib import Path
import pandas as pd
import docx


def task_func(source_directory: str, target_directory: str) -> int:
    source_path = Path(source_directory)
    if not source_path.exists() or not source_path.is_dir():
        raise FileNotFoundError(source_directory)

    target_path = Path(target_directory)
    os.makedirs(target_path, exist_ok=True)

    def extract_txt_or_csv(file_path: Path) -> str:
        return file_path.read_text(encoding="utf-8", errors="replace")

    def extract_docx(file_path: Path) -> str:
        document = docx.Document(str(file_path))
        parts = []

        for paragraph in document.paragraphs:
            text = paragraph.text.strip()
            if text:
                parts.append(text)

        for table in document.tables:
            for row in table.rows:
                for cell in row.cells:
                    text = cell.text.strip()
                    if text:
                        parts.append(text)

        return "\n".join(parts)

    def extract_xlsx(file_path: Path) -> str:
        parts = []
        excel_file = pd.ExcelFile(file_path)

        for sheet_name in excel_file.sheet_names:
            df = pd.read_excel(excel_file, sheet_name=sheet_name, header=None, dtype=object)
            if df.empty:
                continue
            for value in df.stack(dropna=True).tolist():
                if pd.isna(value):
                    continue
                text = str(value).strip()
                if text:
                    parts.append(text)

        return "\n".join(parts)

    extractors = {
        ".txt": extract_txt_or_csv,
        ".csv": extract_txt_or_csv,
        ".docx": extract_docx,
        ".xlsx": extract_xlsx,
    }

    converted = 0

    for file_path in sorted(source_path.iterdir()):
        if not file_path.is_file():
            continue

        extractor = extractors.get(file_path.suffix.lower())
        if extractor is None:
            continue

        try:
            text_content = extractor(file_path)
            output_file = target_path / f"{file_path.stem}.csv"
            pd.DataFrame({"Text": [text_content]}).to_csv(output_file, index=False)
            converted += 1
        except Exception:
            continue

    return converted

import pandas as pd
